package com.youngone.mediacontrol.identity.api;
import com.youngone.mediacontrol.identity.application.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.util.UUID;
@RestController@RequestMapping("/api/v1/hr")public class HrIntegrationController{private final HrSourceService sources;private final CsvHrImportService imports;public HrIntegrationController(HrSourceService sources,CsvHrImportService imports){this.sources=sources;this.imports=imports;}@PostMapping("/sources")@ResponseStatus(HttpStatus.CREATED)public HrModels.SourceResponse create(@RequestHeader("X-Admin-Id")String actor,@Valid@RequestBody HrModels.SourceCreate request){return new HrModels.SourceResponse(sources.create(request,actor));}@PostMapping(value="/sources/{sourceId}/imports/csv",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public HrModels.ImportResponse csv(@PathVariable UUID sourceId,@RequestParam(defaultValue="true")boolean dryRun,@RequestHeader("X-Admin-Id")String actor,@RequestPart("file")MultipartFile file)throws IOException{return imports.importCsv(sourceId,file.getBytes(),dryRun,actor);}}